import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.E8pQZ6KS.js";const f=JSON.parse('{"title":"专业与课程地图","description":"","frontmatter":{},"headers":[],"relativePath":"课程地图.md","filePath":"课程地图.md","lastUpdated":1792430298000}'),l={name:"课程地图.md"};function o(h,t,i,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="专业与课程地图" tabindex="-1">专业与课程地图 <a class="header-anchor" href="#专业与课程地图" aria-label="Permalink to &quot;专业与课程地图&quot;">​</a></h1><blockquote><p>本节基于福建农林大学官方公开资料整理，帮助你快速看懂「网络空间安全专业」四年要学什么、课程之间的依赖关系是什么。<strong>开课学期与授课教师以学校教务最新安排为准。</strong></p></blockquote><h2 id="专业基本信息" tabindex="-1">专业基本信息 <a class="header-anchor" href="#专业基本信息" aria-label="Permalink to &quot;专业基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>专业名称</td><td>网络空间安全</td></tr><tr><td>专业代码</td><td>080911TK</td></tr><tr><td>所属门类 / 专业类</td><td>工学 / 计算机类</td></tr><tr><td>学位授予</td><td>工学学士</td></tr><tr><td>修业年限</td><td>四年</td></tr><tr><td>首次招生</td><td>2020 年（网络空间安全系 2020 年 6 月成立）</td></tr><tr><td>前身</td><td>网络工程专业（2009 年招生）</td></tr><tr><td>培养单位</td><td>计算机与信息学院</td></tr><tr><td>培养特色</td><td>「政校企三位一体」「以赛促学、以赛促教」；2024 年获批福建省「网络空间安全现代产业学院」省级立项</td></tr></tbody></table><h2 id="四年知识脉络" tabindex="-1">四年知识脉络 <a class="header-anchor" href="#四年知识脉络" aria-label="Permalink to &quot;四年知识脉络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>学年</th><th>主线</th><th>关键能力</th></tr></thead><tbody><tr><td>地基期</td><td>大一</td><td>公共课 + 编程入门 + 数学</td><td>会写程序、会用工具</td></tr><tr><td>筑基期</td><td>大二</td><td>计算机专业基础 + 安全导论</td><td>懂系统、懂网络、懂密码学基础</td></tr><tr><td>主攻期</td><td>大三</td><td>核心安全课程密集展开</td><td>攻防 / 逆向 / 取证 / 隐私等方向成型</td></tr><tr><td>综合期</td><td>大四</td><td>攻防综合实践 + 毕业设计</td><td>独立完成安全项目，衔接深造或就业</td></tr></tbody></table><h2 id="核心课程安排-参考专业设置申请表" tabindex="-1">核心课程安排（参考专业设置申请表） <a class="header-anchor" href="#核心课程安排-参考专业设置申请表" aria-label="Permalink to &quot;核心课程安排（参考专业设置申请表）&quot;">​</a></h2><p>以下为专业申报时的核心课程及开课学期（源自《福建农林大学网络空间安全专业本科专业设置申请表》）：</p><table tabindex="0"><thead><tr><th>学期</th><th>核心课程</th><th>学时</th><th>拟授课教师（申报时）</th></tr></thead><tbody><tr><td>第 2 学期</td><td>数据结构与算法</td><td>48</td><td>刘雄恩</td></tr><tr><td>第 2 学期</td><td>网络空间安全导论</td><td>16</td><td>柳晓龙</td></tr><tr><td>第 3 学期</td><td>高级程序设计</td><td>48</td><td>刘必雄</td></tr><tr><td>第 3 学期</td><td>信息安全数学基础</td><td>40</td><td>连海峰</td></tr><tr><td>第 3 学期</td><td>现代密码学</td><td>48</td><td>陈日清</td></tr><tr><td>第 4 学期</td><td>汇编语言</td><td>48</td><td>詹仕华</td></tr><tr><td>第 4 学期</td><td>操作系统及安全</td><td>48</td><td>林莉莉</td></tr><tr><td>第 4 学期</td><td>数据库原理及安全</td><td>48</td><td>刘必雄</td></tr><tr><td>第 4 学期</td><td>网络安全原理</td><td>48</td><td>纪祥敏</td></tr><tr><td>第 4 学期</td><td>安全协议分析</td><td>48</td><td>周术诚</td></tr><tr><td>第 4 学期</td><td>计算机病毒原理与防范</td><td>48</td><td>王长缨</td></tr><tr><td>第 5 学期</td><td>软件安全</td><td>48</td><td>舒兆港</td></tr><tr><td>第 5 学期</td><td>计算机取证</td><td>48</td><td>陈建章</td></tr><tr><td>第 5 学期</td><td>网络安全法律与伦理</td><td>16</td><td>赖建华</td></tr><tr><td>第 6 学期</td><td>网络攻防技术</td><td>48</td><td>黄日茂</td></tr></tbody></table><h2 id="主干课程全景-学院最新专业介绍" tabindex="-1">主干课程全景（学院最新专业介绍） <a class="header-anchor" href="#主干课程全景-学院最新专业介绍" aria-label="Permalink to &quot;主干课程全景（学院最新专业介绍）&quot;">​</a></h2><p>根据学院《网络空间安全专业介绍》（2026 年更新），主干课程包括：</p><blockquote><p>网络空间安全数学基础、数据结构、汇编语言、高级语言程序设计、操作系统安全、数据库安全、密码学基础、网络攻防原理与技术、软件逆向工程、网络舆情安全技术、安全协议分析、防火墙原理与技术、数字取证、大数据安全与隐私保护等。</p></blockquote><p>此外，专业师资还覆盖以下方向课程（以实际开课为准）：</p><ul><li><strong>安全技术</strong>：入侵检测技术、可信计算、防火墙原理与技术、信息隐藏技术、信息内容安全</li><li><strong>前沿方向</strong>：物联网安全、云计算与虚拟化安全、人工智能及安全、移动安全</li><li><strong>基础支撑</strong>：通信系统原理与安全、信息论与编码、编译原理、离散数学、线性代数、概率论与数理统计、专业英语、网络安全前沿技术讲座</li></ul><h2 id="实践性教学环节" tabindex="-1">实践性教学环节 <a class="header-anchor" href="#实践性教学环节" aria-label="Permalink to &quot;实践性教学环节&quot;">​</a></h2><ul><li><strong>课程设计</strong>：数据结构（课程设计）、数据库安全（课程设计）、操作系统安全（课程设计）等</li><li><strong>综合实训</strong>：网络攻防实训、安全综合实验（校内网络安全虚拟仿真实验系统、信息安全实训平台等）</li><li><strong>毕业设计</strong>：大四学年完成</li><li><strong>学科竞赛</strong>：全国大学生信息安全竞赛、CTF 系列赛事等（学院「以赛促学」特色）</li></ul><div class="tip custom-block"><p class="custom-block-title">怎么读这张地图</p><p>课程之间的依赖关系比顺序更重要：<strong>数学（信息安全数学基础）→ 密码学（现代密码学）→ 安全协议分析</strong> 是一条主线；<strong>编程 + 数据结构 + 操作系统 + 网络</strong> 是所有安全方向的共同地基。想深入哪条线，可以先看 <a href="./学习规划.html">四年学习规划</a> 和对应方向的课程页。</p></div><h2 id="信息来源" tabindex="-1">信息来源 <a class="header-anchor" href="#信息来源" aria-label="Permalink to &quot;信息来源&quot;">​</a></h2><ul><li><a href="https://www.fafu.edu.cn/_upload/article/files/8e/d3/e357ab4943cbb011fff5bf4dd861/c72f5d5a-37ab-454f-9eb2-eb6c3a676aa0.pdf" target="_blank" rel="noreferrer">福建农林大学网络空间安全专业本科专业设置申请表（PDF）</a></li><li><a href="https://xxxy.fafu.edu.cn/22/72/c12013a402034/page.htm" target="_blank" rel="noreferrer">计算机与信息学院：网络空间安全专业介绍</a></li><li><a href="https://xxxy.fafu.edu.cn/wlkjaqx/listm.htm" target="_blank" rel="noreferrer">计算机与信息学院：网络空间安全系</a></li><li><a href="https://xxxy.fafu.edu.cn/lsyg/listm.htm" target="_blank" rel="noreferrer">计算机与信息学院：历史沿革</a></li></ul>',19)])])}const u=d(l,[["render",o]]);export{f as __pageData,u as default};
